"""Webhook request handling for Linkweave billing events."""

from __future__ import annotations

import json
import os
from collections.abc import Mapping
from typing import Any

from event_store import append_event
from signature_utils import verify_signature


SIGNATURE_HEADER = "X-Webhook-Signature"
SECRET_ENV_VAR = "WEBHOOK_SECRET"
REQUIRED_EVENT_FIELDS = ("event_id", "event_type", "account_id")


def _rejected(reason: str) -> dict[str, Any]:
    return {"status": "rejected", "reason": reason}


def _header_value(headers: Mapping[str, Any], name: str) -> Any:
    """Fetch a header value, tolerating proxies that normalise key case."""

    if name in headers:
        return headers[name]
    wanted = name.lower()
    for key, value in headers.items():
        if isinstance(key, str) and key.lower() == wanted:
            return value
    return None


def _raw_body(request: Mapping[str, Any]) -> bytes | None:
    body = request.get("body")
    if isinstance(body, (bytes, bytearray, memoryview)):
        return bytes(body)
    return None


def _is_payment_event(event: Any) -> bool:
    if not isinstance(event, Mapping):
        return False
    for field in REQUIRED_EVENT_FIELDS:
        value = event.get(field)
        if not isinstance(value, str) or not value.strip():
            return False
    return True


def handle_webhook(request: Mapping[str, Any]) -> dict[str, Any]:
    """Validate and enqueue one payment event."""

    if not isinstance(request, Mapping):
        return _rejected("malformed request")

    headers = request.get("headers")
    if not isinstance(headers, Mapping):
        return _rejected("malformed request")

    body = _raw_body(request)
    if body is None:
        return _rejected("malformed request")

    secret = os.environ.get(SECRET_ENV_VAR, "")
    if not secret:
        return _rejected("receiver secret unavailable")

    signature = _header_value(headers, SIGNATURE_HEADER)
    if not isinstance(signature, str) or not signature.strip():
        return _rejected("missing signature")

    if not verify_signature(body, signature, secret):
        return _rejected("invalid signature")

    try:
        event = json.loads(body.decode("utf-8"))
    except ValueError:
        return _rejected("invalid json")

    if not _is_payment_event(event):
        return _rejected("invalid event")

    append_event(event)
    return {"status": "accepted", "event_id": event["event_id"]}
