"""Authentication and validation behaviour for the Linkweave receiver."""

from __future__ import annotations

import json
import os
import tempfile
import unittest

from signature_utils import signature_for
from webhooks import handle_webhook


VALID_EVENT = {
    "event_id": "evt-sec-001",
    "event_type": "invoice.paid",
    "account_id": "acct-001",
}


class WebhookSecurityTests(unittest.TestCase):
    def setUp(self):
        self.secret = "unit-test-webhook-secret"
        self.log = tempfile.NamedTemporaryFile(delete=False)
        self.log.close()
        os.environ["WEBHOOK_SECRET"] = self.secret
        os.environ["WEBHOOK_EVENTS"] = self.log.name

    def tearDown(self):
        os.unlink(self.log.name)
        os.environ.pop("WEBHOOK_SECRET", None)
        os.environ.pop("WEBHOOK_EVENTS", None)

    def signed(self, event, secret=None, body=None):
        payload = json.dumps(event, sort_keys=True).encode("utf-8") if body is None else body
        return {
            "headers": {"X-Webhook-Signature": signature_for(payload, secret or self.secret)},
            "body": payload,
        }

    def queued(self):
        with open(self.log.name, encoding="utf-8") as handle:
            return [json.loads(line) for line in handle if line.strip()]

    def assertRejected(self, request):
        response = handle_webhook(request)
        self.assertEqual(response.get("status"), "rejected")
        self.assertNotEqual(response.get("status"), "accepted")
        self.assertEqual(self.queued(), [])
        return response

    def test_missing_signature_header_is_rejected(self):
        body = json.dumps(VALID_EVENT, sort_keys=True).encode("utf-8")
        self.assertRejected({"headers": {}, "body": body})

    def test_blank_signature_header_is_rejected(self):
        body = json.dumps(VALID_EVENT, sort_keys=True).encode("utf-8")
        self.assertRejected({"headers": {"X-Webhook-Signature": ""}, "body": body})

    def test_forged_signature_is_rejected(self):
        body = json.dumps(VALID_EVENT, sort_keys=True).encode("utf-8")
        self.assertRejected(
            {"headers": {"X-Webhook-Signature": signature_for(body, "attacker-secret")}, "body": body}
        )

    def test_tampered_body_is_rejected(self):
        original = json.dumps(VALID_EVENT, sort_keys=True).encode("utf-8")
        tampered = json.dumps(dict(VALID_EVENT, account_id="acct-attacker"), sort_keys=True).encode("utf-8")
        request = self.signed(VALID_EVENT, body=tampered)
        request["headers"]["X-Webhook-Signature"] = signature_for(original, self.secret)
        self.assertRejected(request)

    def test_missing_secret_fails_closed(self):
        os.environ.pop("WEBHOOK_SECRET")
        body = json.dumps(VALID_EVENT, sort_keys=True).encode("utf-8")
        self.assertRejected(
            {"headers": {"X-Webhook-Signature": signature_for(body, "")}, "body": body}
        )

    def test_malformed_requests_are_rejected(self):
        for request in (
            {},
            {"body": b"{}"},
            {"headers": {}},
            {"headers": "X-Webhook-Signature: sha256=00", "body": b"{}"},
            {"headers": {}, "body": json.dumps(VALID_EVENT)},
        ):
            with self.subTest(request=request):
                self.assertEqual(handle_webhook(request).get("status"), "rejected")
        self.assertEqual(self.queued(), [])

    def test_invalid_json_is_rejected(self):
        self.assertRejected(self.signed(VALID_EVENT, body=b"{not json"))

    def test_non_utf8_body_is_rejected(self):
        self.assertRejected(self.signed(VALID_EVENT, body=b'{"event_id": "\xff\xfe"}'))

    def test_non_object_json_is_rejected(self):
        self.assertRejected(self.signed(VALID_EVENT, body=b"[1, 2, 3]"))

    def test_missing_event_fields_are_rejected(self):
        for field in ("event_id", "event_type", "account_id"):
            partial = {key: value for key, value in VALID_EVENT.items() if key != field}
            with self.subTest(missing=field):
                self.assertRejected(self.signed(partial))

    def test_non_string_event_fields_are_rejected(self):
        for field in ("event_id", "event_type", "account_id"):
            broken = dict(VALID_EVENT)
            broken[field] = 12345
            with self.subTest(field=field):
                self.assertRejected(self.signed(broken))

    def test_blank_event_fields_are_rejected(self):
        self.assertRejected(self.signed(dict(VALID_EVENT, event_id="   ")))

    def test_lowercase_signature_header_is_accepted(self):
        request = self.signed(VALID_EVENT)
        request["headers"] = {"x-webhook-signature": request["headers"]["X-Webhook-Signature"]}
        self.assertEqual(
            handle_webhook(request),
            {"status": "accepted", "event_id": "evt-sec-001"},
        )

    def test_accepted_event_is_queued_once_with_extra_fields_preserved(self):
        event = dict(VALID_EVENT, amount=4200, currency="USD")
        self.assertEqual(
            handle_webhook(self.signed(event)),
            {"status": "accepted", "event_id": "evt-sec-001"},
        )
        self.assertEqual(self.queued(), [event])


if __name__ == "__main__":
    unittest.main()
